-- Insert Quiz Questions for Lesson: Using Templates Without Sounding Robotic

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'using-templates' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson using-templates not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main risk of using templates?', 
    '["They send too quickly","They can sound cold or generic if not personalized","They cost more to send","They don''t work with mobile"]'::jsonb,
    'They can sound cold or generic if not personalized',
    'Templates save time but can feel impersonal. The key is to use them as a starting point and add personal details that show you''re paying attention.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does ''Template first, personal touch second'' mean?', 
    '["Send the template, then send a personal message","Start with a template, then customize it with specific details","Create templates after writing personal messages","Templates are more important than personalization"]'::jsonb,
    'Start with a template, then customize it with specific details',
    'Use the template as your foundation, then add personal touches like referencing their specific question, using their name, or mentioning details from their situation.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these is a good use for templates?', 
    '["Every single message should be a template","Repetitive replies like new lead responses, booking confirmations, and follow-ups","Only for complaints","Templates should never be used"]'::jsonb,
    'Repetitive replies like new lead responses, booking confirmations, and follow-ups',
    'Templates are perfect for situations where you send similar messages repeatedly - new leads, booking replies, price questions, follow-ups, etc.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


