-- Insert Quiz Questions for Lesson: What to Do After You Reply

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'after-you-reply' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson after-you-reply not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you update the contact record after replying?', 
    '["It''s required by law","To ensure follow-up doesn''t fall through the cracks","To delete the conversation","It''s not necessary to update records"]'::jsonb,
    'To ensure follow-up doesn''t fall through the cracks',
    'Updating records after replying ensures you have context for future conversations and that next steps are tracked and not forgotten.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does ''The message is not finished until the next step is recorded'' mean?', 
    '["You should keep messaging until they respond","Sending a reply is only part of the process - you also need to document what happens next","You must record phone calls","All messages should be recorded on video"]'::jsonb,
    'Sending a reply is only part of the process - you also need to document what happens next',
    'The reply handles the immediate conversation, but recording the next step (tag, note, opportunity, appointment) ensures proper follow-up happens.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these should you do after replying to a hot lead?', 
    '["Delete the conversation","Add a note, update tags, and create or update an opportunity","Wait for them to reply again","Mark it as spam"]'::jsonb,
    'Add a note, update tags, and create or update an opportunity',
    'For hot leads, you should document the conversation with notes, apply appropriate tags, and track them in your opportunity pipeline.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


