-- Insert Quiz Questions for Lesson: Daily Inbox Routine

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'daily-inbox-routine' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson daily-inbox-routine not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How often should you check your Conversations Inbox?', 
    '["Every 5 minutes all day long","Three times per day: morning, midday, and end of day","Only once per week","Never - it checks itself"]'::jsonb,
    'Three times per day: morning, midday, and end of day',
    'A 10-minute routine three times per day keeps you responsive without making you live in the inbox. This balances responsiveness with productivity.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you focus on during the midday inbox check?', 
    '["All messages equally","Hot leads - people asking about price, booking, or how to start","Only spam messages","Deleting old conversations"]'::jsonb,
    'Hot leads - people asking about price, booking, or how to start',
    'Midday is for priority responses to hot leads who are actively interested and ready to take action.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main goal of having an inbox routine?', 
    '["To spend all day in the inbox","To control the inbox efficiently without it controlling you","To avoid talking to leads","To automate all responses"]'::jsonb,
    'To control the inbox efficiently without it controlling you',
    'The routine helps you stay on top of conversations efficiently so you can respond to leads promptly while still having time for other important work.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
